from __future__ import absolute_import
import re
import time
import logging
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException
from taf.selenium.sbts.common.exceptions import ObjectNotFoundException, AddObjectException
from taf.selenium.sbts.pages.panels.navigation import NavigationPanel
from taf.selenium.sbts.pages.panels.view import ViewPanel
from taf.selenium.sbts.pages.panels.details import DetailPanel
from taf.selenium.sbts.pages.v25r2.modals import (CreateNewConfigurationModal,
                                                  AddObjectModal,
                                                  RemoveObjectModal,
                                                  UndoChangesModal,
                                                  SaveBtsConfigurationModal,
                                                  SaveReportModal,
                                                  ActivatePlanModal,
                                                  LoadScfFileModal,
                                                  UndoObjectChangesModal,
                                                  AddNewObjectModal)


class ConfigurationCommonAction(NavigationPanel, ViewPanel, DetailPanel):

    _LOAD_COMMISSIONING_FILE_BUTTON_SCRIPT = "form p-fileupload input"
    _LOAD_SCF_FILE_BROWSER_BUTTON_XPATH = "//form//p-fileupload//input"
    _CREATE_CONFIGURATION_BUTTON_XPATH = '//button[span[contains(text(), "Create Plan")]]'
    _LOAD_COMMISSIONING_FILE_BUTTON_XPATH = '//button[span[contains(text(), "Load SCF")]]'
    _UNDO_CHANGES_BUTTON_XPATH = '//button[span[contains(text(), "Undo Changes")]]'
    _VALIDATE_PLAN_BUTTON_XPATH = '//button[span[contains(text(), "Validate Plan")]]'
    _ACTIVATE_PLAN_BUTTON_XPATH = '//button[span[contains(text(), "Activate Plan")]]'
    _SAVE_REPORT_BUTTON_XPATH = '//button[span[contains(text(), "Save Report")]]'
    _SAVE_BTS_CONFIGURATION_ICON_XPATH = '//button[span[contains(text(), "Save Plan")]]'
    _OBJECT_NAME_FILTER_XPATH = ('//input[contains(@class, "p-inputtext") and '
                                 'contains(@ng-reflect-ng-class, "object") and @placeholder="Filter"]')

    _OBJECT_NAME_XPATH = "//div[@role='treeitem' or @aria-label='{}']"

    _ADD_OBJECT_BUTTON_XPATH = _OBJECT_NAME_XPATH + "//p-button[@ng-reflect-text='Copy child managed object from']"
    _ADD_NEW_OBJECT_BUTTON_XPATH = _OBJECT_NAME_XPATH + "//p-button[@ng-reflect-text='Create new child managed objec']"
    _REMOVE_OBJECT_BUTTON_XPATH = _OBJECT_NAME_XPATH + "//p-button[@ng-reflect-text='Delete managed object']"
    _UNDO_OBJECT_CHANGES_BUTTON_XPATH = _OBJECT_NAME_XPATH + "//p-button[@ng-reflect-text='Restore deleted managed object']"

    _VALID_OBJECT_XPATH = ('//*[contains(text(), "{}")]/ancestor::*[contains(@class, '
                           'tree-list-grouping-renderer ng-scope)]//span[@aria-label="{}"]')

    _VALID_OBJECT_BASE_XPATH = '//blocks-navigation//cdk-virtual-scroll-viewport//ul[@role="tree"]'

    _TARGET_OBJECT_XPATH = 'p-treenode[li/div[@aria-label="{}"]]'

    _OBJECT_NAME_MAP_XPATH = ('//*[contains(text(), "{}")]/ancestor::*[contains(@class, '
                              '"tree-list-grouping-renderer ng-scope")]//span[contains(@aria-label, "{}")]')
    _VALIDATION_SUCCEEDED_XPATH = "//div[contains(text(), 'Validation operation succeeded')]"
    _INACTIVE_CONFIGURATION_XPATH = ('//*[contains(text(), "Inactive BTS configurations")]'
                                     '/ancestor::div[div[@class="ui-expandable-panel-header"]]'
                                     '//following-sibling::div[contains(@class, "ui-expandable-panel-body")]'
                                     '//li[@role="button"]')

    _SCROLL_TOP = 'return document.querySelector("blocks-navigation cdk-virtual-scroll-viewport").scrollTop;'
    _SCROLL_TO_TOP = 'return document.querySelector("blocks-navigation cdk-virtual-scroll-viewport").scrollTop = 0;'

    _SCROLL = ('var scroll_bar = document.querySelector(\'blocks-navigation cdk-virtual-scroll-viewport\'); '
               'if (scroll_bar){{scroll_bar.scrollTop={};}}')
    _CHECK_IF_ON_BOTTOM = (
        'var scroll_bar = document.querySelector(\'blocks-navigation cdk-virtual-scroll-viewport\'); if ('
        'scroll_bar.scrollHeight - scroll_bar.scrollTop - scroll_bar.clientHeight < 2) {{return 1}} else {{return 0}} ')

    _VALIDATE_HARDWARE_BUTTON_XPATH = '//div[@role="dialog"]//p-button[@ng-reflect-label="Validate"]'

    _STEP = 120
    _instance = None
    _CURRENT = 'Current'
    _SUB_STR = r'\/following-sibling::li\[div\/\/span\[\@aria-label="{}"\]\]\[1\]'
    _DISTANCE_FROM_STOP = 0

    _SELECT_PLAN_TEXT_XPATH = '//label[contains(text(), "Select plan")]/following-sibling::p-dropdown/div/span/div'
    _SELECT_PLAN_DROPDOWN_XPATH ='//label[contains(text(), "Select plan")]/following-sibling::p-dropdown/div/span'
    _SELECT_PLAN_ITEM_XPATH = '//ul[@role="listbox"]//p-dropdownitem/li//div[contains(text(), "{}")]'

    _DEFAULT_PLAN_NAME = "CURRENT_BTS_CONF-1"
    _CLOSE_VALIDATION_ERROR_XPATH = ('//button[@aria-label="collapse button" and'
                                     ' .//span[contains(@class, "mdi-chevron-down")]]')

    _EXPANDED_TREEITEM_XPATH = '//cdk-virtual-scroll-viewport//li[@aria-expanded="true" and @data-level!="0"]/div/button/span'

    _PARAMETER_EDITOR_TAB_XPATH = '//div[@class="ui-view-panel-nav-tab-name ng-binding" and text()="Parameter Editor"]'

    _LOCATED_OBJECT_MAX_LEVEL = 5
    _LOCATED_OBJECT_MIN_LEVEL = 1

    _CONFIGURATION_MANAGEMENT_TITLE_XPATH = '//div[contains(text(), "Configuration Management")]'

    def __init__(self, driver, download_checker=None, screenshot_dir=None):
        super(ConfigurationCommonAction, self).__init__(driver, download_checker, screenshot_dir)

    def _unexpand_treeitems(self):
        elems = self.driver.find_elements_by_xpath(self._EXPANDED_TREEITEM_XPATH)
        for elem in elems[::-1]:
            try:
                elem.click()
            except:
                logging.info("ignore unexpand tree item failed")
                continue

            time.sleep(1)

    def _go_to_target_object(self, bts_configuration, object_name_list, scroll_time=45):  # noqa: C901
        single = False
        located = False

        locate_previous_xpath = ""
        locate_current_xpath = ""
        object_element_xpaths = []
        self._close_validation_error()
        self.driver.execute_script(self._SCROLL_TO_TOP)
        time.sleep(1)
        for index, object_name in enumerate(object_name_list):
            if index > 1:
                head_o = re.findall(r'aria-label="(.*?)"', locate_previous_xpath)
                if (object_name_list[index - 1] not in head_o and index != 0) or (single is True and located is False):
                    raise ObjectNotFoundException("can not locate {} in route {} on "
                                                  "webem".format(object_name_list[index - 1], "/".join(object_name_list)))

            current = self._TARGET_OBJECT_XPATH.format(object_name)
            object_element_xpaths.append(current)

            for loop in range(0, scroll_time):
                try:
                    locate_current_xpath = self._locate_object_element_and_return_xpath(object_element_xpaths)
                    locate_previous_xpath = locate_current_xpath
                    located = True
                    break
                except TimeoutException:
                    if not self.driver.execute_script(self._CHECK_IF_ON_BOTTOM):
                        scroll_top = float(self.driver.execute_script(self._SCROLL_TOP))
                        self.driver.execute_script(self._SCROLL.format(scroll_top + self._STEP))
                        time.sleep(2)

                try:
                    locate_current_xpath = self._locate_object_element_and_return_xpath(object_element_xpaths)
                    locate_previous_xpath = locate_current_xpath
                    located = True
                    break
                except TimeoutException:
                    located = False
                    if len(re.findall(r'aria-label="(.*?)"', locate_current_xpath)) == 1:
                        single = True
                        continue

                try:
                    if not locate_previous_xpath:
                        break

                    """
                    The previous xpath is not visable when located the current xpath.
                    Then ignore the previous xpath and locate the current xpath with the base xpath.
                    """
                    if self.elements_is_visible((By.XPATH, locate_previous_xpath), 0.8):
                        locate_current_xpath = self._VALID_OBJECT_BASE_XPATH + '/' + '/following-sibling::'.join(object_element_xpaths[-2:])
                        self.wait_for_enable((By.XPATH, locate_current_xpath), 1)
                        locate_previous_xpath = locate_current_xpath
                        located = True
                        break
                    else:
                        try_locate_current_xpath = self._VALID_OBJECT_BASE_XPATH + '/' + current
                        self.wait_for_enable((By.XPATH, try_locate_current_xpath), 0.8)
                        locate_current_xpath = try_locate_current_xpath
                        locate_previous_xpath = locate_current_xpath
                        located = True
                        break
                except TimeoutException:
                     located = False
                     continue

        logging.info("located '{}' xpath for object {}".format(locate_current_xpath, object_name))
        return locate_current_xpath + '//span[@class="ot-highlight-text"]'

    def _locate_object_element_and_return_xpath(self, object_element_xpaths):
        locate_current_xpaths = []
        if len(object_element_xpaths) == 1:
            xpath = self._VALID_OBJECT_BASE_XPATH + '/' + object_element_xpaths[0]
            locate_current_xpaths.append(xpath)
        else:
            for index in range(self._LOCATED_OBJECT_MAX_LEVEL, self._LOCATED_OBJECT_MIN_LEVEL, -1):
                xpath = self._VALID_OBJECT_BASE_XPATH + '/' + '/following-sibling::'.join(object_element_xpaths[-index:])
                if xpath not in locate_current_xpaths:
                    locate_current_xpaths.append(xpath)

        for locate_current_xpath in locate_current_xpaths:
            try:
                self.wait_for_enable((By.XPATH, locate_current_xpath), 1)
                elem = self.driver.find_element_by_xpath(locate_current_xpath)
                self._driver.execute_script("arguments[0].scrollIntoView();", elem)
                return locate_current_xpath
            except:
                continue
        else:
            raise TimeoutException

    def _close_validation_error(self):
        if self.element_exists((By.XPATH, self._CLOSE_VALIDATION_ERROR_XPATH)):
            self.click_enabled_element((By.XPATH, self._CLOSE_VALIDATION_ERROR_XPATH))

    def _input_and_choose_object(self, object_name, timeout=60, bts_configuration='Current'):
        """
        Choose object after inputting object name
        :param object_name: str, where object will be added in
        :param timeout: int, timeout
        """
        self.driver.execute_script(self._SCROLL.format(self._DISTANCE_FROM_STOP))
        formated_bts_configuration = bts_configuration.lower().capitalize()
        object_name_list = object_name.split('/')
        last_level_object_name = object_name_list[-1]
        self._input_object(last_level_object_name, bts_configuration, timeout)
        self._choose_object(object_name_list, formated_bts_configuration)
        return last_level_object_name

    def _input_object(self, object_name, bts_configuration, timeout):
        self.driver.execute_script(self._SCROLL.format(self._DISTANCE_FROM_STOP))

        if self._CURRENT == bts_configuration:
            bts_configuration = self._DEFAULT_PLAN_NAME

        current_selected_plan = self._get_selected_plan()
        if current_selected_plan != bts_configuration:
            self._select_plan(bts_configuration)

        self.insert_text_to_enable_element_and_enter((By.XPATH, self._OBJECT_NAME_FILTER_XPATH),
                                                     object_name,
                                                     timeout)

    def _get_selected_plan(self):
        return self.get_text((By.XPATH, self._SELECT_PLAN_TEXT_XPATH))

    def _select_plan(self, bts_configuration):
        self.click_enabled_element((By.XPATH, self._SELECT_PLAN_DROPDOWN_XPATH))
        self.click_enabled_element((By.XPATH, self._SELECT_PLAN_ITEM_XPATH.format(bts_configuration)))

    def _choose_object(self, object_name_list, bts_configuration):
        target_object_xpath = self._go_to_target_object(bts_configuration, object_name_list)

        retry = 3
        while retry:
            try:
                elem = self.driver.find_element_by_xpath(target_object_xpath)
                elem.click()
                return
            except:
                try:
                    elem = self.driver.find_element_by_xpath(target_object_xpath)
                    self.driver.execute_script("arguments[0].click();", elem)
                    return
                except:
                    retry -= 1
                    time.sleep(1)
                    continue
        raise ObjectNotFoundException("target object '{}' not clicked".format(target_object_xpath))

    def add_object(self, object_name, object_class_name, plan_to_copy_from, copy_from, include_subobject, id_value,
                   is_load_default_values, timeout):
        self._unexpand_treeitems()
        if plan_to_copy_from and copy_from:
            logging.info("copy existing object for adding an object")
            self.copy_existing_object(object_name=object_name,
                                      class_name=object_class_name,
                                      source_plan_name=plan_to_copy_from,
                                      source_managed_object=copy_from,
                                      copy_object_with_subtree=include_subobject,
                                      object_id=id_value,
                                      timeout=timeout)
        else:
            logging.info("create new object for adding an object")
            self.add_new_object(object_name, object_class_name, id_value, timeout)

    def add_new_object(self, object_name, class_name, object_id, timeout=60):
        """
        Add new object under navigation panel
        :param object_name: str, name of object class
        :param class_name: str, name of class name you want to add.
        :param object_id: str, object id
        :param timeout: int, timeout
        """
        object_name = self._input_and_choose_object(object_name)

        add_new_object_button_xpath = self._ADD_NEW_OBJECT_BUTTON_XPATH.format(object_name)
        self.perform_element_hover(locator=(By.XPATH, add_new_object_button_xpath))
        self.click_enabled_element((By.XPATH, add_new_object_button_xpath),  timeout)

        add_new_object_modal = AddNewObjectModal(self.driver)
        add_new_object_modal.wait_until_add_object_modal_appear(timeout)
        add_new_object_modal.add_object(class_name,
                                        object_id,
                                        timeout)
        add_new_object_modal.submit(timeout)
        time.sleep(1)
        self._unexpand_treeitems()

    def copy_existing_object(self,
                             object_name,
                             class_name,
                             source_plan_name,
                             source_managed_object,
                             copy_object_with_subtree,
                             object_id,
                             timeout=60):
        """
        Adding object under navigation panel
        :param object_name: str, where object will be added in
        :param class_name: str, name of object class
        :param source_plan_name: str, where plan to copy object from
        :param source_managed_object: str, where copy object from
        :param copy_object_with_subtree: boolean
        :param object_id: str, default is None
        :param timeout: int, timeout
        """
        object_name = self._input_and_choose_object(object_name)

        """
        click parameter editor tab to advoid object operation button covered by notice message.
        """
        self.click_enabled_element((By.XPATH, self._PARAMETER_EDITOR_TAB_XPATH),
                                    timeout)
        time.sleep(1)

        add_object_button_xpath = self._ADD_OBJECT_BUTTON_XPATH.format(object_name)
        self.click_enabled_element((By.XPATH, add_object_button_xpath),
                                   timeout)

        add_object_modal = AddObjectModal(self.driver)
        add_object_modal.wait_until_add_object_modal_appear(timeout)
        retry = 3
        while retry:
            try:
                add_object_modal.add_object(class_name,
                                            plan_to_copy_from=source_plan_name,
                                            copy_from=source_managed_object,
                                            include_subobject=copy_object_with_subtree,
                                            id_value=object_id,
                                            timeout=timeout)
                add_object_modal.submit(timeout)
                time.sleep(1)
                self._unexpand_treeitems()
                return
            except:
                logging.warning("add object failed, try {} again".format(retry))
                retry -= 1
                time.sleep(1)
                continue
        raise AddObjectException("add object failed, please check the object name")

    def remove_object(self, object_name, timeout=60, raise_non_exist=False):
        """
        Remove object under navigation panel
        :param object_name: str, object will be removed
        :param timeout: int, timeout
        """
        try:
            object_name = self._input_and_choose_object(object_name, timeout)
        except ObjectNotFoundException as msg:
            if not raise_non_exist:
                return
            else:
                raise ObjectNotFoundException(msg)

        """
        click parameter editor tab to advoid object operation button covered by notice message.
        """
        self.click_enabled_element((By.XPATH, self._PARAMETER_EDITOR_TAB_XPATH),
                                    timeout)
        time.sleep(1)

        remove_object_button_xpath = self._REMOVE_OBJECT_BUTTON_XPATH.format(object_name)
        self.click_enabled_element((By.XPATH, remove_object_button_xpath), timeout)
        remove_object_modal = RemoveObjectModal(self.driver)
        remove_object_modal.wait_until_remove_object_modal_appear(timeout)
        remove_object_modal.submit(timeout)

    def undo_object_changes(self, object_name, timeout=60):
        """
        Remove object under navigation panel
        :param object_name: str, object will be removed
        :param timeout: int, timeout
        """
        object_name = self._input_and_choose_object(object_name, timeout)

        undo_object_change_button_xpath = self._UNDO_OBJECT_CHANGES_BUTTON_XPATH.format(object_name)
        self.perform_element_hover(locator=(By.XPATH, undo_object_change_button_xpath))
        self.click_enabled_element((By.XPATH, undo_object_change_button_xpath),
                                   timeout)

        undo_object_changes_modal = UndoObjectChangesModal(self.driver)
        undo_object_changes_modal.wait_until_undo_object_changes_modal_appear(timeout)
        undo_object_changes_modal.submit(timeout)

    def create_plan(self, is_copy, copy_configuration_from, configuration_name, timeout):
        self.click_enabled_element((By.XPATH, self._CREATE_CONFIGURATION_BUTTON_XPATH), timeout)
        configuration_modal = CreateNewConfigurationModal(self.driver)
        configuration_modal.wait_for_creat_new_configuration_modal_appear(timeout)
        configuration_modal.create_new_configuration(is_copy, copy_configuration_from, configuration_name, timeout)

    def load_commissioning_file_and_check_load_status(self, file_path, timeout=60):
        """
        Load commissioning file and check load status
        :param file_path: str, scf file path
        :param timeout: int, timeout
        :return: boolean, True or False
        """
        self.click_enabled_element((By.XPATH, self._LOAD_COMMISSIONING_FILE_BUTTON_XPATH), timeout)
        self.load_file_from_hidden_button(self._LOAD_COMMISSIONING_FILE_BUTTON_SCRIPT,
                                          self._LOAD_SCF_FILE_BROWSER_BUTTON_XPATH,
                                          file_path,
                                          timeout)
        load_scf_file_modal = LoadScfFileModal(self.driver)
        load_scf_file_modal.wait_until_load_file_modal_appear(timeout)
        load_scf_file_modal.load_scf()
        load_status = load_scf_file_modal.check_status_after_loading_scf_file(timeout)
        load_scf_file_modal.close()
        return load_status

    def undo_changes(self, timeout=60):
        """
        Undo changes
        :param timeout: int, timeout
        """
        self.click_enabled_element((By.XPATH, self._UNDO_CHANGES_BUTTON_XPATH), timeout)

        undo_changes_modal = UndoChangesModal(self.driver)
        undo_changes_modal.wait_until_undo_changes_modal_appear(timeout)
        undo_changes_modal.execute_undo_changes(timeout)

    def validate_plan(self, timeout=60):
        """
        Validate definition errors plan
        :return: str, validation result
        """
        self.click_enabled_element((By.XPATH, self._VALIDATE_PLAN_BUTTON_XPATH), timeout)
        try:
            self.wait_for_visibility_by_xpath(self._VALIDATION_SUCCEEDED_XPATH, 30)
        except TimeoutException:
            if self.element_exists((By.XPATH, self._VALIDATE_HARDWARE_BUTTON_XPATH)):
                self.click_enabled_element((By.XPATH, self._VALIDATE_HARDWARE_BUTTON_XPATH), 3)
            self.wait_for_visibility_by_xpath(self._VALIDATION_SUCCEEDED_XPATH, 30)

    def activate_plan(self, download_plan_without_activation=False,
                      activate_plan_despite_errors=False, execute=True, activate_inactive_plan=False, timeout=60):
        """
        Activate plan after loading scf file
        :param download_plan_without_activation: boolean, if False, download plan without activation will not be
        selected, default False
        :param activate_plan_despite_errors: boolean, if True, activate or download plan despite of validation errors
        will be selected, default False
        :param execute: boolean, if True, click execute button, otherwise close the activate plan modal
        :param timeout: int, timeout
        :return: boolean, if True, activate successfully, otherwise, activate failed
        """
        activate_status = False
        if activate_inactive_plan:
            self.wait_for_visibility_by_xpath(self._INACTIVE_CONFIGURATION_XPATH)
            self.click_enabled_element((By.XPATH, self._INACTIVE_CONFIGURATION_XPATH), timeout)

        self.perform_element_hover_by_xpath(self._CONFIGURATION_MANAGEMENT_TITLE_XPATH)
        try:
            self.click_enabled_element((By.XPATH, self._ACTIVATE_PLAN_BUTTON_XPATH), timeout=20)
        except TimeoutException:
            return activate_status

        activate_plan_modal = ActivatePlanModal(self.driver)
        activate_plan_modal.wait_until_actiavte_plan_modal_appear(timeout)
        if not activate_inactive_plan:
            activate_plan_modal.select_download_plan_without_activation(download_plan_without_activation)
        activate_plan_modal.select_activate_or_download_plan_despite_errors(activate_plan_despite_errors, timeout=10)

        if execute:
            activate_status = activate_plan_modal.execute(timeout)
        activate_plan_modal.close(timeout)
        return activate_status

    def save_report(self, timeout=60):
        """
        Save report
        :param timeout: int, timeout
        :return: str, report path
        """
        self.click_enabled_element((By.XPATH, self._SAVE_REPORT_BUTTON_XPATH))

        save_report_modal = SaveReportModal(self.driver, self._download_checker)
        save_report_modal.wait_until_save_report_modal_appear(timeout)
        report_file_path = save_report_modal.save_report(timeout)
        save_report_modal.close(timeout)
        return report_file_path

    def save_bts_configuration(self, save_configuration_type_str, save_planned_parameter_changes):
        """
        Keyword for save bts configuration
        :param save_configuration_type_str: str, type of save type
                0: Save as SCF - BTS configuration only
                1: Save as full BTS runtime configuration
                2: Save BTS runtime information only
        :param save_planned_parameter_changes: bool, save the planned parameter changes or not
        :return str, path to download configuration file
        """
        self.click_enabled_element_after_visible((By.XPATH, self._SAVE_BTS_CONFIGURATION_ICON_XPATH))
        save_configuration_modal = SaveBtsConfigurationModal(self.driver, self._download_checker)
        save_configuration_modal.wait_until_save_bts_configuration_modal_appear()
        return save_configuration_modal.save(save_configuration_type_str, save_planned_parameter_changes)
